pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small gaps that cannot fit any more items
    if post_residual < item_size {
        score += 150.0 * (item_size - post_residual) as f64;
    }

    // Penalize open bins to encourage filling them up
    if open_bins_count > 2 {
        score += 7.5 * open_bins_count as f64;
    }

    // Reward better utilization of the mean residual
    if mean_residual < 30.0 {
        score -= 2.5 * (30.0 - mean_residual);
    } else if mean_residual > 70.0 {
        score -= 1.0 * (mean_residual - 70.0);
    }

    // Penalize bins that are too full to fit the next item
    if post_residual < next_item_size / 3 {
        score += 25.0 * (next_item_size / 3 - post_residual) as f64;
    }

    score
}

