pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins with small remaining space
    if post_residual < 15 {
        score -= 8.0;
    }

    // Reward using bins that can fit the next item as well
    if fitting_bins_count > 3 {
        score += 4.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Penalize opening new bins
    score -= 1.7;

    // Reward using bins with a mean residual close to the bin capacity
    let residual_ratio = mean_residual / bin_capacity as f64;
    if (residual_ratio - 0.5).abs() < 0.2 {
        score += 4.5;
    }

    // Penalize if the next item is large and cannot fit in any open bins
    if next_item_size > bin_capacity && fitting_bins_count == 0 {
        score -= 18.0;
    }

    // Reward using bins with a post-residual close to zero (full utilization)
    if post_residual < 3 {
        score += 3.0;
    }

    // Penalize if the step is near the end and there are open bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 && open_bins_count > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize if the bin is almost full and we have a large lookahead item
    if bin_residual <= 20 && next_item_size > 50 {
        score += (bin_residual as f64 / 10.0).powi(2);
    }

    // Reward if the bin has enough space to fit the next two items
    if post_residual >= next_item_size + item_size {
        score -= ((post_residual as f64 - (next_item_size + item_size)) / 10.0).powi(3);
    }

    // Penalize if the residual is significantly lower than the mean residual
    if post_residual < mean_residual * 0.5 {
        score += (mean_residual * 0.5 - post_residual) as f64;
    }

    // Reward if the bin has a fitting open bin that can fit the item
    if fitting_bins_count > 0 {
        score -= ((fitting_bins_count as f64 / open_bins_count as f64) * 2.0).powi(2);
    }

    // Penalize if creating a new bin would be beneficial (e.g., very small residual)
    if post_residual < 10 && open_bins_count > 0 {
        score += ((10 - post_residual) as f64 / 5.0).powi(3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating bins with too little residual space
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Reward using bins efficiently
    if bin_residual > 50 {
        score -= (bin_residual - 50) as f64 / 10.0;
    } else if bin_residual < 25 {
        score += (25 - bin_residual) as f64 * 2.0;
    }

    // Penalize opening new bins
    if fitting_bins_count == 0 {
        score += 7.5;
    }

    // Reward using a bin that can fit the next item without creating too much extra space
    if post_residual > next_item_size && next_item_size < bin_capacity / 3 {
        score -= (post_residual - next_item_size) as f64 / 12.0;
    } else if post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Penalize bins that are close to being full
    if bin_residual < 20 {
        score += (20 - bin_residual) as f64 * 3.0;
    }

    // Reward using a bin with a smaller mean residual
    score -= mean_residual / 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize creating unusable dead space
    if post_residual < 5.0 {
        score += 100.0;
    }

    // Reward bins that can fit the next item more aggressively
    if fitting_bins_count > 0 && next_item_size <= bin_capacity - bin_residual {
        score -= (next_item_size as f64 / mean_residual) * 30.0;
    }

    // Penalize opening new bins too frequently more harshly
    if open_bins_count > 3 {
        score += 50.0 * (open_bins_count - 3) as f64;
    }

    // Reward bins with less residual space to encourage filling them up more aggressively
    if post_residual < mean_residual / 4.0 {
        score -= (mean_residual / 4.0 - post_residual) as f64 * 25.0;
    }

    // Penalize high step index (earlier in the stream) more harshly
    if step_index < total_items / 8 {
        score += 30.0 * ((total_items / 8) - step_index) as f64;
    }

    score
}
